use genewars_runtime::{building_power::*,physics_tables::PhysicsTables};use std::{fs,path::PathBuf};
fn main(){let p=PathBuf::from(std::env::args().nth(1).unwrap());let input=fs::read(p.join("input.bin")).unwrap();let physics=PhysicsTables::from_mapped_bytes(&fs::read(p.join("angles.bin")).unwrap(),&fs::read(p.join("bounce.bin")).unwrap()).unwrap();let mut out=Vec::new();for c in input.chunks_exact(148){let before:[u8;81]=c[..81].try_into().unwrap();let target=c[81..].try_into().unwrap();let a=plan_transfer_motion(&before,6272,0,1632,[3136;4],128,&physics).unwrap();let plan=plan_power_delivery(&a,Some(&target),6272).unwrap();out.extend(plan.effect_after);out.extend(plan.target_after.unwrap());out.push(u8::from(plan.retire_requested));}fs::write(p.join("actual.bin"),out).unwrap();}
